[
  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "My claim is only about who chooses work after an attempt has failed: the steward. Another agent proposed a machine pattern saying only steward can create any record at any time. Should we accept that pattern now? Please represent the result of your review.",
      "status": "recorded",
      "meta": {
        "source_kind": "verbatim",
        "speaker": "user"
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "pattern-steward-only-create",
    "value": {
      "type": "extraction",
      "text": "Reported machine pattern from another agent, as relayed by the user: only steward can create any record at any time.",
      "status": "proposed",
      "meta": {
        "pattern_standing": "proposed",
        "source_kind": "paraphrase",
        "proposer": "another agent (identity not supplied)",
        "review_state": "reviewed-not-accepted",
        "review_note": "Not accepted. Broader than the accepted claim in two respects: it removes the after-failed-attempt condition and it governs performing create-record rather than deciding choose-next-work. Acceptance would require an explicit user decision covering that wider scope."
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "pattern-steward-only-create-governs",
    "value": {
      "from": "pattern-steward-only-create",
      "type": "governs",
      "to": "create-record"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "pattern-steward-only-create-about",
    "value": {
      "from": "pattern-steward-only-create",
      "type": "about",
      "to": "steward-role"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "pattern-steward-only-create-source",
    "value": {
      "from": "pattern-steward-only-create",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "pattern-steward-only-create-conflict",
    "value": {
      "from": "pattern-steward-only-create",
      "type": "potential-conflict",
      "to": "steward-next-work",
      "explanation": "The pattern generalizes the accepted claim beyond its stated scope: any record at any time, and creation rather than choice. The user states the claim is only about who chooses work after a failed attempt."
    }
  },
  {
    "op": "update",
    "collection": "nodes",
    "id": "steward-next-work",
    "value": {
      "meta": {
        "scope_note": "Per the user (source-4), this claim is only about who chooses work after an attempt has failed. It does not state who may perform create-record in general.",
        "sources": [
          "source-2",
          "source-4"
        ]
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-steward-next-work-1",
    "value": {
      "from": "steward-next-work",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "record-creation-scope",
    "value": {
      "type": "question",
      "text": "Outside the failed-attempt case, is there any rule restricting which role may perform create-record, or is record creation unconstrained by the steward-next-work claim?",
      "status": "open",
      "meta": {
        "answer_shape": "condition",
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Raised by the other agent's broader pattern; the user's stated claim does not answer it."
      }
    }
  },
  {
    "op": "add",
